const fs=require('fs'),path=require('path');const root=path.resolve(__dirname,'..'),out=path.join(root,'catalog-parametri-functii'),stats=JSON.parse(fs.readFileSync(path.join(out,'acoperire.json'))),dex=JSON.parse(fs.readFileSync(path.join(out,'dex-summary.json'))),values=JSON.parse(fs.readFileSync(path.join(out,'clase-valori.json')));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=x=>x.toLocaleString('ro-RO');
