function page(title,body,mode='',scripts=''){return '<!doctype html><html lang="ro"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · iFLYTEK</title><link rel="stylesheet" href="catalog.css"></head><body'+(mode?' data-mode="'+mode+'"':'')+'><header><div class="eyebrow">iFLYTEK · APK 1.0.3899 · 30 octombrie 2026</div><h1>'+esc(title)+'</h1>'+nav+'</header>'+body+'<footer>Analiză statică, fără validare pe ochelari sau cloud. Fiecare sens este legat de clasă, funcție și versiune. <a href="acoperire.json">Acoperire</a> · <a href="validare.json">Verificări</a> · <a href="CITESTE.txt">Regenerare și formatul datelor</a></footer>'+scripts+'</body></html>';}
const cards=[['PARAMETRI.html','Dicționar de parametri',num(stats.parameters),'fișe distincte: tip, format, valori, condiții, sursă și funcții asociate.'],['FUNCTII.html','Catalog de funcții',num(stats.functions),'fișe ale contractelor și mecanismelor analizate, inclusiv intrări, ieșiri și erori observate.'],['APK_COMPLET.html','Inventar structural complet',num(dex.functions),'metode DEX, cu argumente, retururi și legături către clasa declarantă.']];
let overview='<div class="wrap"><p>Două dicționare separate, legate în ambele sensuri. Intrările cu același nume rămân distincte când aparțin unor protocoale sau clase diferite. Fiecare fișă păstrează dovezile și aspectele care nu pot fi stabilite din cod.</p><div class="cards">'+cards.map(([url,title,n,desc])=>'<article><a href="'+url+'"><h2>'+title+'</h2></a><div class="metric">'+n+'</div><p>'+desc+'</p></article>').join('')+'</div><p class="note">Inventarul DEX include și bibliotecile terțe, constructorii și metodele sintetice. Acoperirea structurală completă nu înseamnă că toate acestea sunt API-uri ale ochelarilor sau că semantica lor a fost reconstituită.</p><h2>Ce este documentat în fișele detaliate</h2><div class="cards">'+Object.entries(stats.byKind).map(([k,v])=>'<div class="card"><div class="metric">'+v+'</div>'+esc(k)+'</div>').join('')+'</div><p>DTO: '+stats.schemas+' clase / clase imbricate. Canale Flutter: '+stats.channelClasses+' clase inspectate; '+stats.confirmedFlutterFunctions+' ramuri atribuite. Alte '+stats.unresolvedChannelCandidates+' șiruri candidate sunt păstrate în <a href="audit-flutter.json">audit</a>; includ și evenimente sau enumuri, deci nu sunt numărate ca funcții confirmate.</p><h2>Cum se citește o fișă</h2><ol><li>Identificați funcția și contextul: BLE, Wi-Fi, cloud sau apel local Flutter.</li><li>Deschideți parametrul pentru tip, format pe fir, unitate, valori și regula de omitere. O valoare observată nu garantează întregul domeniu acceptat.</li><li>Verificați sursa și linia. Valorile implicite ale constructorului, valorile de rezervă ale parserului și constantele pe fir sunt marcate separat.</li><li>Folosiți funcțiile asociate pentru traseul cerere → parser de răspuns → strat de transport.</li></ol><h2>Exporturi pentru prelucrare</h2><div class="links"><a href="parametri.json">Parametri JSON</a><a href="parametri.csv">Parametri CSV</a><a href="functii.json">Funcții JSON</a><a href="functii.csv">Funcții CSV</a><a href="scheme.json">Clase și câmpuri DTO</a><a href="clase-valori.json">Clase de valori JSON</a><a href="catalog-apk-sqlite.zip">Bază SQLite completă ZIP</a><a href="surse-sha256.json">Amprentele surselor</a></div><p>Baza SQLite are '+num(dex.classes)+' clase, '+num(dex.functions)+' funcții, '+num(dex.inputParameters)+' parametri de intrare, '+num(dex.returnParameters)+' retururi și '+num(dex.fields)+' câmpuri. Sunt definite chei de legătură și indecși pentru căutare.</p><h2>Limite cunoscute</h2><ul>'+stats.limitations.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul><p>Au fost folosite sursele și rapoartele locale din APK, <a href="../protocol-comunicare/INDEX.html">analiza protocolului</a> și <a href="../documentatie/arhive-sdk/INDEX.html">catalogul documentațiilor SDK</a>. Materialele generale SDK nu sunt atribuite automat acestui model de ochelari.</p><p><small>APK SHA-256: <code>'+stats.apkSha256+'</code></small></p></div>';
if(fs.existsSync(path.join(root,'imbunatatire-raspunsuri/INDEX.html')))overview='<p id="analiza-raspunsuri" style="padding:16px;background:#e9f5ef;border-left:4px solid #24694f"><a href="../imbunatatire-raspunsuri/INDEX.html"><strong>Analiza solicitărilor și îmbunătățirea răspunsurilor</strong></a> · Indicatori, dovezi și limite.</p>'+overview;
