function catalogPage(title,mode,note,placeholder,scripts){return page(title,'<div class="wrap"><p>'+note+'</p><div class="toolbar"><input id="search" type="search" placeholder="'+esc(placeholder)+'" aria-label="Căutare"><select id="filter" aria-label="Filtru"></select></div><p id="count" aria-live="polite"></p><div class="pager"><button id="prev">Înapoi</button><span id="page"></span><button id="next">Înainte</button></div><div class="layout"><aside id="results" class="results" aria-label="Rezultate"></aside><article id="detail" class="detail"><h2>Selectați o intrare</h2><p>Fișa apare aici. Linkurile directe pot fi copiate din bara de adrese.</p></article></div></div>',mode,scripts);}
